const root=document.querySelector('#indiretos-view');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Todos','Escritório','Limpeza','Cozinha','EPIs','Uniformes'];
let rows=[],category='Todos',tab='Pedidos',search='';
const num=s=>{let t=String(s??'').trim().replace(/\s/g,'');if(t.includes(','))t=t.replace(/\./g,'').replace(',','.');return Number(t)||0};
const iso=s=>{const m=String(s||'').match(/^(\d{2})\/(\d{2})\/(\d{4})/);return m?m[3]+'-'+m[2]+'-'+m[1]:''};
const br=s=>s?s.slice(8,10)+'/'+s.slice(5,7)+'/'+s.slice(0,4):'—';
function classify(name,group){let s=name.toUpperCase();if(group==='epis')return /CAMISETA|CALCA|CALÇA|UNIFORME|JALECO/.test(s)?'Uniformes':'EPIs';if(/PAPEL TOALHA|VASSOUR|ESPONJA|DETERGENTE|DESINFET|SABAO|SABÃO|LIMPEZA|ESCOVA|AROMATIZ/.test(s))return 'Limpeza';if(/COPO|CAFÉ|CAFE|FILTRO DE PAPEL|GUARDANAPO|COZINHA/.test(s))return 'Cozinha';return 'Escritório'}
function parseCSV(text,group){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(s=>s.trim());const split=line=>{let out=[],v='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){v+='"';i++}else q=!q}else if(c===';'&&!q){out.push(v.trim());v=''}else v+=c}out.push(v.trim());return out};const headers=split(lines.shift()).map(s=>s.toLowerCase().replace(/\s+/g,' ').trim());const get=(cols,name)=>cols[headers.indexOf(name)]||'';if(!headers.includes('cód. item')||!headers.includes('dt. entrega')||!headers.includes('quantidade'))throw Error('CSV incompatível: verifique as colunas Cód. Item, Dt. Entrega e Quantidade.');return lines.map(line=>{const c=split(line),code=get(c,'cód. item'),order=get(c,'ordem'),delivery=iso(get(c,'dt. entrega')),description=get(c,'descrição');return {id:[order,code,delivery].join('|'),code,order,description,quantity:num(get(c,'quantidade')),unit:get(c,'um'),purchase:iso(get(c,'dt. compra')),delivery,company:get(c,'emp.'),type:get(c,'tipo'),category:classify(description,group),status:'Pendente',stock:null,safety:null,consumption:null,lead:null}}).filter(x=>x.code)}
async function load(){try{const r=await fetch('/api/indirect-materials',{cache:'no-store'});if(!r.ok)throw Error('Não foi possível carregar os materiais.');const j=await r.json();rows=j.items||[];render()}catch(e){root.innerHTML='<section class="panel"><h3>Materiais Indiretos</h3><p>'+esc(e.message)+'</p></section>'}}
async function save(){const r=await fetch('/api/indirect-materials',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:rows})});const j=await r.json();if(!r.ok)throw Error(j.error||'Falha ao salvar.')}
const today=()=>new Date().toLocaleDateString('en-CA');
function filtered(){return rows.filter(x=>(category==='Todos'||x.category===category)&&(!search||[x.code,x.description,x.order].join(' ').toLowerCase().includes(search.toLowerCase())))}
function status(x){return x.status==='Recebido'?'Recebido':x.status==='Cancelado'?'Cancelado':x.delivery&&x.delivery<today()?'Atrasado':x.status||'Pendente'}
function render(){if(!root)return;const f=filtered(),late=rows.filter(x=>status(x)==='Atrasado').length,upcoming=rows.filter(x=>x.status!=='Recebido'&&x.delivery>=today()).length;
root.innerHTML=`<div class="ind-head"><div><h2>Materiais Indiretos</h2><p>Escritório, limpeza, cozinha, EPIs e uniformes · base independente</p></div><div><label class="ind-upload">📥 Importar CSV <input type="file" accept=".csv,text/csv" data-import hidden multiple></label><button type="button" data-export>⬇ Exportar CSV</button></div></div>
<div class="ind-kpis"><div><small>Itens com pedidos</small><strong>${rows.length}</strong></div><div><small>Categorias</small><strong>5</strong></div><div><small>Entregas programadas</small><strong>${upcoming}</strong></div><div><small>Pedidos atrasados</small><strong>${late}</strong></div></div>
<div class="ind-filter"><div class="ind-categories">${categories.map(c=>`<button type="button" data-category="${c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div><input data-search type="search" placeholder="Buscar código, item ou pedido" value="${esc(search)}"></div>
<div class="ind-tabs">${['Pedidos','Estoque / MRP','Prazos'].map(t=>`<button type="button" data-tab="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div>
${tab==='Pedidos'?table(['Código / material','Categoria','Pedido','Quantidade','Entrega prevista','Situação'],f.map(x=>`<tr><td><b>${esc(x.code)}</b><br>${esc(x.description)}</td><td>${esc(x.category)}</td><td>${esc(x.order)}</td><td>${esc(x.quantity)} ${esc(x.unit)}</td><td>${br(x.delivery)}</td><td><select data-status-id="${esc(x.id)}">${['Pendente','Recebido','Cancelado'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select><small class="ind-state">${status(x)==='Atrasado'?'⚠️ Atrasado':''}</small></td></tr>`)):tab==='Estoque / MRP'?table(['Código / material','Categoria','Saldo físico','Segurança','Consumo mensal','Reposição (dias)','Necessidade'],f.map(x=>{const need=x.stock==null||x.safety==null?'Aguardando saldo e parâmetros':x.stock<x.safety?'⚠️ Abaixo da segurança':'Dentro da segurança';return `<tr><td><b>${esc(x.code)}</b><br>${esc(x.description)}</td><td>${esc(x.category)}</td>${['stock','safety','consumption','lead'].map(k=>`<td><input class="ind-number" type="number" min="0" step="any" data-value-id="${esc(x.id)}" data-field="${k}" value="${x[k]??''}" placeholder="—"></td>`).join('')}<td>${need}</td></tr>`})):`<div class="ind-dates"><label>De <input type="date" data-from value="${root.dataset.from||''}"></label><label>Até <input type="date" data-to value="${root.dataset.to||''}"></label></div>`+table(['Data prevista','Código / material','Pedido','Quantidade','Situação'],f.filter(x=>(!root.dataset.from||x.delivery>=root.dataset.from)&&(!root.dataset.to||x.delivery<=root.dataset.to)).sort((a,b)=>a.delivery.localeCompare(b.delivery)).map(x=>`<tr><td>${br(x.delivery)}</td><td>${esc(x.code)} · ${esc(x.description)}</td><td>${esc(x.order)}</td><td>${esc(x.quantity)} ${esc(x.unit)}</td><td>${status(x)}</td></tr>`))}
<p class="method-note">O CSV de necessidades/pedidos não informa saldo físico. O estoque e os parâmetros MRP devem ser conferidos com os relatórios do Focco3i antes de calcular reposições. Importações são consolidadas pelo pedido, código e data prevista.</p><p data-feedback role="status"></p>`;
root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;render()});root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});root.querySelector('[data-search]').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();const i=root.querySelector('[data-search]');i.focus();i.setSelectionRange(pos,pos)};
root.querySelector('[data-import]').onchange=async e=>{try{let added=0;for(const file of e.target.files){const buf=await file.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(buf);if(text.includes('�'))text=new TextDecoder('windows-1252').decode(buf);const group=/epi|uniform/i.test(file.name)?'epis':'other';const incoming=parseCSV(text,group),map=new Map(rows.map(x=>[x.id,x]));for(const item of incoming){map.set(item.id,{...item,...(map.get(item.id)||{}),description:item.description,quantity:item.quantity,delivery:item.delivery})}rows=[...map.values()];added+=incoming.length}await save();render();root.querySelector('[data-feedback]').textContent=added+' registros processados e salvos.'}catch(err){root.querySelector('[data-feedback]').textContent='Erro na importação: '+err.message}};
root.querySelectorAll('[data-status-id]').forEach(el=>el.onchange=async()=>{const x=rows.find(x=>x.id===el.dataset.statusId);if(!x)return;const old=x.status;x.status=el.value;try{await save();render()}catch(e){x.status=old;alert(e.message)}});
root.querySelectorAll('[data-value-id]').forEach(el=>el.onchange=async()=>{const x=rows.find(x=>x.id===el.dataset.valueId),k=el.dataset.field;if(!x)return;const old=x[k];x[k]=el.value===''?null:Math.max(0,num(el.value));try{await save();render()}catch(e){x[k]=old;alert(e.message)}});
root.querySelectorAll('[data-from],[data-to]').forEach(el=>el.onchange=()=>{root.dataset[el.dataset.from!==undefined?'from':'to']=el.value;render()});
root.querySelector('[data-export]').onclick=()=>{const heads=['Categoria','Código','Descrição','Pedido','Quantidade','UM','Compra','Entrega','Situação','Estoque','Segurança','Consumo','Reposição'];const data=filtered().map(x=>[x.category,x.code,x.description,x.order,x.quantity,x.unit,br(x.purchase),br(x.delivery),status(x),x.stock??'',x.safety??'',x.consumption??'',x.lead??'']);const csv='\uFEFF'+[heads,...data].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='materiais-indiretos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
}
function table(heads,rs){return '<div class="table-scroll"><table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+(rs.length?rs.join(''):'<tr><td colspan="'+heads.length+'">Nenhum item. Importe os CSVs do Focco3i para começar.</td></tr>')+'</tbody></table></div>'}
load();window.addEventListener('hashchange',()=>{if(location.hash==='#indiretos')load()});
